package main

// drawIcon paints the app icon (a mandarin with a leaf) in a size×size square.
// Used for the Windows tray icon and the Linux desktop icon
// (the .exe icon is generated by scripts/mkrsrc.py).
func drawIcon(cv Canvas, size int) {
	s := float64(size) / 32
	px := func(v float64) int { return int(v*s + 0.5) }
	cv.Circle(px(16), px(18), px(13), argb(255, 255, 140, 0))                    // fruit
	cv.Circle(px(11), px(13), px(3), argb(255, 255, 180, 80))                    // highlight
	cv.RadialEllipse(px(20.5), px(4.5), 0, 0, 11*s, 7*s, argb(255, 76, 175, 80)) // leaf (horizontal)
	cv.RadialEllipse(px(16), px(6), -90, 0, 4*s, 2*s, argb(255, 90, 60, 30))     // stalk (vertical)
}
